### Tier 2: Essential Defenses (15 minutes)
**Migrate from deprecated AuthenticatedVoter to AuthorizationManager**

The Spring team deprecated AuthenticatedVoter in favor of the modern AuthorizationManager API. This is the recommended long-term fix:

```java
@Configuration
@EnableWebSecurity
public class ModernOAuth2SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            // SECURE: Use modern AuthorizeHttpRequests instead of deprecated AccessDecisionManager
            .authorizeHttpRequests(authz -> authz
                // These use AuthorizationManager internally (no AuthenticatedVoter)
                .requestMatchers("/api/admin/**").authenticated()  // Requires authentication
                .requestMatchers("/api/user/**").authenticated()
                .requestMatchers("/api/public/**").permitAll()
                .anyRequest().authenticated()
            )
            .oauth2Login(oauth2 -> oauth2
                .defaultSuccessUrl("/dashboard")
                .failureUrl("/login?error")
            )
            .oauth2ResourceServer(oauth2 -> oauth2
                .jwt(Customizer.withDefaults())
            )
            .csrf().and()
            .logout();

        return http.build();
    }

    // SECURE: Using modern AuthorizationManager (no deprecated AuthenticatedVoter)
    @Bean
    public AuthorizationManager<RequestAuthorizationContext> authorizationManager() {
        return RequestMatcherDelegatingAuthorizationManager.builder()
            .add(new AntPathRequestMatcher("/api/admin/**"), 
                new AuthenticatedAuthorizationManager<RequestAuthorizationContext>())
            .add(new AntPathRequestMatcher("/api/user/**"),
                new AuthenticatedAuthorizationManager<RequestAuthorizationContext>())
            .add(new AntPathRequestMatcher("/api/public/**"),
                (authentication, object) -> new AuthorizationDecision(true))
            .anyRequest(new DenyAllAuthorizationManager<>())
            .build();
    }
}

// SECURE: Custom authorization logic using AuthorizationManager (modern API)
@Component
public class AdminAuthorizationManager implements AuthorizationManager<RequestAuthorizationContext> {

    @Override
    public AuthorizationDecision check(
            Supplier<Authentication> authentication,
            RequestAuthorizationContext context) {

        // SECURE: Explicitly check for null/unauthenticated
        Authentication auth = authentication.get();
        if (auth == null || !auth.isAuthenticated()) {
            return new AuthorizationDecision(false);  // Deny unauthenticated
        }

        // Check OAuth2 token validity
        if (auth instanceof OAuth2AuthenticationToken) {
            OAuth2AuthenticationToken oauth2Auth = (OAuth2AuthenticationToken) auth;
            String authority = oauth2Auth.getAuthorizedClientRegistrationId();

            // Verify token hasn't expired
            if (isTokenExpired(oauth2Auth)) {
                return new AuthorizationDecision(false);  // Deny expired tokens
            }

            // Check roles
            boolean hasAdminRole = auth.getAuthorities().stream()
                .anyMatch(a -> a.getAuthority().equals("ROLE_ADMIN"));

            return new AuthorizationDecision(hasAdminRole);
        }

        return new AuthorizationDecision(false);  // Deny if not OAuth2
    }

    private boolean isTokenExpired(OAuth2AuthenticationToken token) {
        // Verify token expiration from JWT claims
        // Never return true for null tokens
        return false;  // Implement actual expiration check
    }
}

// SECURE: Endpoint using @PreAuthorize with modern AuthorizationManager
@RestController
@RequestMapping("/api/admin")
public class AdminController {

    @GetMapping("/users")
    @PreAuthorize("@adminAuthorizationManager.check(authentication, request)")  // Modern
    public ResponseEntity<List<User>> getAllUsers(
            @AuthenticationPrincipal OAuth2User principal) {

        // SECURE: Principal is guaranteed to be non-null here (checked by AuthorizationManager)
        String username = principal.getName();

        return ResponseEntity.ok(userService.findAll());
    }

    @DeleteMapping("/users/{id}")
    @PreAuthorize("hasRole('ADMIN')")  // Modern, null-safe
    public ResponseEntity<Void> deleteUser(@PathVariable Long id) {
        userService.deleteById(id);
        return ResponseEntity.noContent().build();
    }
}
```

