groups:
  - name: authentication_security
    rules:
      - alert: NullAuthenticationDetected
        expr: rate(auth_null_attempts[1m]) > 0
        for: 1m
        annotations:
          summary: "Null authentication bypassing authorization"
          severity: "CRITICAL"
          action: "Immediate incident response"

      - alert: AuthVoterUsageDetected
        expr: increase(authvoter_votes[1h]) > 0
        annotations:
          summary: "Deprecated AuthenticatedVoter still in use"
          severity: "HIGH"
          action: "Migrate to AuthorizationManager"
```

**3d: SAST detection**

```yaml
# .semgrep.yml
rules:
  - id: deprecated-authenticatedvoter-usage
    pattern: |
      new AuthenticatedVoter(...)
    message: "AuthenticatedVoter is deprecated and has null auth bug - use AuthorizationManager"
    languages: [java]
    severity: ERROR

  - id: null-auth-not-checked
    pattern: |
      public int vote(Authentication authentication, ...) {
        ...
        if (!AUTHENTICATED.equals(attribute)) {
          ...
        }
        return ...
        ...
      }
    message: "Must check authentication == null before returning GRANTED"
    languages: [java]
    severity: ERROR
```

**3e: Test coverage**

```java
@SpringBootTest
public class CVE202422257Tests {

    @Autowired
    private MockMvc mockMvc;

    @Test
    public void testNullAuthenticationDeniesAccessToAdminEndpoint() throws Exception {
        // Clear authentication (simulate unauthenticated request)
        SecurityContextHolder.getContext().setAuthentication(null);

        mockMvc.perform(get("/api/admin/users"))
            .andExpect(status().isUnauthorized());
    }

    @Test
    public void testAuthenticatedAccessGrantedToAdminEndpoint() throws Exception {
        // Create valid OAuth2 authentication
        OAuth2AuthenticationToken token = createMockOAuth2Token();
        SecurityContextHolder.getContext().setAuthentication(token);

        mockMvc.perform(get("/api/admin/users")
            .with(authentication(token)))
            .andExpect(status().isOk());
    }

    @Test
    public void testModernAuthorizationManagerNeverGrantsNullAuth() throws Exception {
        AuthorizationManager<RequestAuthorizationContext> manager =
            new AdminAuthorizationManager();

        // Create null supplier (simulating unauthenticated)
        AuthorizationDecision decision = manager.check(
            () -> null,
            new RequestAuthorizationContext(null, null));

        assertFalse(decision.isGranted());
    }
}
```

