docker run -d --name oauth-lab -p 8180:8080 -e KEYCLOAK_ADMIN=admin -e KEYCLOAK_ADMIN_PASSWORD=admin quay.io/keycloak/keycloak:latest start-dev
# Register test client with PKCE
curl -X POST http://localhost:8180/admin/realms/master/clients -H 'Authorization: Bearer <admin-token>' -d '{"clientId":"test-app","publicClient":true}'
